// GERAR ICS - devolve a agenda de UM comercial em formato iCalendar,
// para subscricao no Google Calendar / Calendario da Apple (feed so de leitura).
// Autenticacao: o comercial_id na query e a unica "chave" deste link - nao e
// suposto ser adivinhavel, mas nao partilhes o URL como se fosse publico.
const F = r => r.fields || r;
const um = v => Array.isArray(v) ? (v[0] || null) : (v || null);

let query = {};
try { query = $('Webhook').first().json.query || {}; } catch (e) {}
const comercialId = (query.comercial_id || '').trim();

if (!comercialId) throw new Error('Falta comercial_id na query (?comercial_id=...)');

const leads = $('Leads').all().map(i => i.json);
const nomeLead = {};
for (const r of leads) { nomeLead[r.id] = F(r).Nome || F(r).nome || 'Lead'; }

const leadsDoComercial = new Set(
  leads.filter(r => {
    const v = F(r).Comercial || F(r).Comerciais || F(r).comercial;
    const ids = Array.isArray(v) ? v : (v ? [v] : []);
    return ids.includes(comercialId);
  }).map(r => r.id)
);

const agenda = $('Agenda').all().map(i => i.json).filter(r => {
  const f = F(r);
  const leadId = um(f.Lead || f.Leads);
  return leadId && leadsDoComercial.has(leadId) && f.estado !== 'cancelado' && f.quando;
});

const pad = n => String(n).padStart(2, '0');
const aUTC = iso => {
  const d = new Date(iso);
  return d.getUTCFullYear() + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate())
    + 'T' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds()) + 'Z';
};
const escapeTxt = s => String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
// RFC 5545: linhas com mais de 75 octetos dobram-se com um espaco no inicio da linha seguinte.
const dobrar = linha => { let out = '', l = linha;
  while (l.length > 75) { out += l.slice(0, 75) + '\r\n '; l = l.slice(75); }
  return out + l;
};

const agora = aUTC(new Date().toISOString());
const DURACAO_MIN = 60;

const linhas = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//CAV//Agenda//PT',
  'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'X-WR-CALNAME:CAV \u2014 Agenda',
  'REFRESH-INTERVAL;VALUE=DURATION:PT1H', 'X-PUBLISHED-TTL:PT1H',
];

for (const r of agenda) {
  const f = F(r);
  const nome = nomeLead[um(f.Lead || f.Leads)] || 'Lead';
  const inicio = new Date(f.quando);
  const fim = new Date(inicio.getTime() + DURACAO_MIN * 60000);
  linhas.push('BEGIN:VEVENT');
  linhas.push(dobrar('UID:' + r.id + '@cav-terminal'));
  linhas.push('DTSTAMP:' + agora);
  linhas.push('DTSTART:' + aUTC(inicio.toISOString()));
  linhas.push('DTEND:' + aUTC(fim.toISOString()));
  linhas.push(dobrar('SUMMARY:' + escapeTxt((f.titulo || 'Compromisso') + ' \u2014 ' + nome)));
  linhas.push('STATUS:CONFIRMED');
  linhas.push('END:VEVENT');
}
linhas.push('END:VCALENDAR');

return [{ json: { ics: linhas.join('\r\n') } }];
